definition.script:
pipeline {
    agent any

    stages {
        stage('Run Checkout Tests') {
            steps {
                sh '''
                    cd D:\\Automation\\playwright_spec
                    npx playwright test tests/Checkout.spec.ts --grep "@regression"
                '''
            }
        }
    }

    post {
        always {
            junit 'test-results/junit.xml'
        }
    }
}
